CREATE OR REPLACE FUNCTION public.icash_claim_owner_batch(p_account uuid, p_primary uuid, p_batch uuid, p_items jsonb, p_preview jsonb, p_config jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.icash_discovery_configs;r public.icash_operation_rates;item jsonb;sid uuid;op text;preview jsonb;person text;
begin
 if p_batch is null or jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items) not between 1 and 5 or octet_length(p_preview::text)>2097152 then return false;end if;
 if not exists(select 1 from jsonb_array_elements(p_items) v where v->>'screeningId'=p_primary::text)
 or (select count(distinct v->>'screeningId') from jsonb_array_elements(p_items) v)<>jsonb_array_length(p_items) then return false;end if;
 if not public.icash_owner_export_people_available((select jsonb_agg(id) from jsonb_array_elements(p_items) i, jsonb_array_elements(i->'ids') id)) then return false;end if;
 perform 1 from public.icash_operating_budget where id=1 for update;
 perform 1 from public.icash_accounts where id=p_account and not bot_paused for update;
 if not found or not public.icash_membership_work_allowed(p_account) then return false;end if;
 select * into c from public.icash_discovery_configs where account_id=p_account for update;
 if (coalesce(c.research_version,0) not in (1,2) and not (coalesce(c.research_version,0)=0 and jsonb_array_length(p_items)=1 and p_config->>'ownerContract'='owner-active-export-v1')) or row(c.contact_rate_id,c.contact_credit_cap,c.property_credit_micros,c.data_rights_until) is distinct from row((p_config->>'rateId')::uuid,(p_config->>'creditCap')::integer,(p_config->>'unitCostMicros')::bigint,(p_config->>'rightsUntil')::timestamptz) then return false;end if;
 select * into r from public.icash_operation_rates where id=c.contact_rate_id;
 if exists(select 1 from icash_research_private.owner_batches where id=p_batch) or (p_preview->'credits' @> '{"used":0,"people":0,"properties":0,"deduplicated":0}'::jsonb) is distinct from true then return false;end if;
 if not public.icash_take_dealmachine_request('owner_lookup',p_account,'owner-batch:'||p_batch,p_batch) then return false;end if;
 for item in select value from jsonb_array_elements(p_items) loop
  sid:=(item->>'screeningId')::uuid;op:='owners:'||p_account||':'||sid;
  if jsonb_typeof(item->'ids') is distinct from 'array' or jsonb_array_length(item->'ids') not between 1 and c.contact_credit_cap then raise exception 'Owner batch audience invalid';end if;
  if sid<>p_primary and exists(select 1 from public.icash_automation_tickets where screening_id=sid) then raise exception 'Owner batch sibling already ticketed';end if;
  if exists(select 1 from public.icash_operation_spend where operation_key=op) then raise exception 'Owner batch operation already exists';end if;
  if exists(select 1 from public.icash_owner_contacts oc join public.icash_screening_jobs prior on prior.id=oc.screening_id where oc.account_id=p_account and prior.snapshot->>'propertyId'=item->'snapshot'->>'propertyId' and oc.created_at>now()-interval '30 days') then raise exception 'Owner batch property already enriched';end if;
  select value into strict preview from jsonb_array_elements(p_preview->'data') where value->>'dm_property_id'=item->'snapshot'->>'propertyId' and value->'found'='true'::jsonb;
  for person in select value from jsonb_array_elements_text(item->'ids') loop
   if person !~ '^per_[a-zA-Z0-9]{1,100}$' or not exists(select 1 from jsonb_array_elements(preview->'contacts') p where p->>'dm_person_id'=person and p->'is_likely_renter' is distinct from 'true'::jsonb and (p->'is_likely_owner'='true'::jsonb or (p->>'is_likely_owner' is null and p->>'contact_type'='owner'))) then raise exception 'Owner batch preview mismatch';end if;
  end loop;
  perform public.icash_reserve_operation(p_account,op,c.contact_rate_id,c.data_rights_until,null,false);
  if not public.icash_claim_owner_enrichment(p_account,sid,op,item->'snapshot',c.contact_rate_id,c.contact_credit_cap,c.property_credit_micros,(r.costs_micros->>'dealmachine')::bigint,c.data_rights_until) then raise exception 'Owner batch admission held';end if;
 end loop;
 insert into icash_research_private.owner_batches(id,account_id,primary_screening,items,preview_receipt) values(p_batch,p_account,p_primary,p_items,p_preview);
 insert into icash_research_private.owner_batch_items select (v->>'screeningId')::uuid,p_batch,'owners:'||p_account||':'||(v->>'screeningId') from jsonb_array_elements(p_items) v;
 return true;
end $function$

CREATE OR REPLACE FUNCTION public.icash_admit_owner_batch(p_account uuid, p_primary uuid, p_batch uuid, p_items jsonb, p_preview jsonb, p_config jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if public.icash_claim_owner_batch(p_account,p_primary,p_batch,p_items,p_preview,p_config) then return 'claimed';end if;
 if exists(select 1 from icash_research_private.requests where id=p_batch and account_id=p_account and kind='owner_lookup' and operation_key='owner-batch:'||p_batch and not admitted)
  and not exists(select 1 from icash_research_private.owner_batches where id=p_batch) then return 'quota_wait';end if;
 return 'held';
end $function$

CREATE OR REPLACE FUNCTION public.icash_admit_owner_active_export(p_account uuid, p_primary uuid, p_batch uuid, p_items jsonb, p_preview jsonb, p_config jsonb, p_request jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ids jsonb;expected jsonb;admission text;item jsonb;person text;preview jsonb;match jsonb;
begin
 if not public.icash_owner_active_export_enabled() then return 'held';end if;
 if jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items) not between 1 and 5 then return 'held';end if;
 select jsonb_agg(to_jsonb(id) order by position) into ids from (
  select v#>>'{}' as id,min(i.ordinality*1000+p.ordinality) as position
  from jsonb_array_elements(p_items) with ordinality i(item,ordinality),jsonb_array_elements(i.item->'ids') with ordinality p(v,ordinality) group by v
 ) u;
 if jsonb_array_length(ids) not between 1 and 125 or exists(select 1 from jsonb_array_elements_text(ids) id where id !~ '^per_[0-9]{1,100}$') then return 'held';end if;
 expected:=jsonb_build_object('people_ids',ids,'fields','["person_full_name","has_active_phone_number"]'::jsonb,'property_match','owner','anchor','person','limit',jsonb_array_length(ids),'require_phone',true,'scrub_dnc',true,'active_phones_only',true);

 if public.icash_owner_targeting_pool(p_account,p_primary)='mobile' then
  if not exists(select 1 from icash_research_private.targeting_settings where id=1 and mobile_verified) then return 'held';end if;
  expected:=expected||'{"mobile_only":true}'::jsonb;end if;
 if exists(select 1 from jsonb_array_elements(p_items) i where public.icash_owner_targeting_pool(p_account,(i->>'screeningId')::uuid)<>public.icash_owner_targeting_pool(p_account,p_primary)) then return 'held';end if;

 if p_request->'fields' is distinct from '[]'::jsonb then return 'held';end if;
 expected:=jsonb_set(expected,'{fields}','[]'::jsonb);
 if exists(select 1 from icash_research_private.owner_exports e where e.request->'fields'='[]'::jsonb
  and e.completed_at is null and e.receipt->'httpStatus'='200'::jsonb) then return 'export_busy';end if;
 if p_request is distinct from expected then return 'held';end if;
 if exists(select 1 from icash_research_private.owner_export_settings where id=1 and preflight_enabled) and not exists(select 1 from icash_research_private.owner_export_preflights p where p.account_id=p_account and p.fingerprint=md5(jsonb_build_array(p_items,p_request)::text) and p.items=p_items and p.request=p_request and p.state='ready' and p.checked_at>clock_timestamp()-interval '30 minutes') then return 'held';end if;
 -- SQL repeats owner/phone availability proof before any quota or wallet claim.
 for item in select value from jsonb_array_elements(p_items) loop
  select value into strict preview from jsonb_array_elements(p_preview->'data') where value->>'dm_property_id'=item->'snapshot'->>'propertyId' and value->'found'='true'::jsonb;
  if (select count(distinct value) from jsonb_array_elements(item->'ids'))<>jsonb_array_length(item->'ids') then return 'held';end if;
  for person in select value from jsonb_array_elements_text(item->'ids') loop
   select value into match from jsonb_array_elements(preview->'contacts') where value->>'dm_person_id'=person limit 1;
   if not found or (match->>'contact_type' is not null and match->>'contact_type'<>'owner')
    or match->'is_likely_renter'='true'::jsonb
    or (match->'is_likely_owner'='true'::jsonb or (match->>'is_likely_owner' is null and match->>'contact_type'='owner')) is distinct from true
    or match->'availability'->'phones'='0'::jsonb then return 'held';end if;
  end loop;
 end loop;
 if not pg_try_advisory_xact_lock(hashtextextended('dealmachine:organization:owner-export',0)) then return 'export_busy';end if;
 if (exists(select 1 from icash_research_private.owner_exports where terminal_at is null and capacity_review_id is null) or icash_research_private.unknown_export_late_capacity_blocked()) then return 'export_busy';end if;
 admission:=public.icash_admit_owner_batch(p_account,p_primary,p_batch,p_items,p_preview,p_config||'{"ownerContract":"owner-active-export-v1"}');
 if admission<>'claimed' then return admission;end if;
 insert into icash_research_private.owner_exports(id,request) values(p_batch,p_request);
 return 'claimed';
end $function$

CREATE OR REPLACE FUNCTION public.icash_record_owner_preflight(p_id uuid, p_lease uuid, p_step text, p_receipt jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p icash_research_private.owner_export_preflights;raw jsonb;d jsonb;n integer;valid boolean:=false;lid jsonb;
begin
 select * into p from icash_research_private.owner_export_preflights where id=p_id for update;
 if not found or p.lease is distinct from p_lease or p_step not in ('create','baseline','eligible','metadata') or p_receipt is null or octet_length(p_receipt::text)>2200000 then return 'held';end if;
 if exists(select 1 from icash_research_private.owner_export_settings where id=1 and preflight_indexing_enabled) and (p_step='metadata'
  or (p_step='create' and p_receipt->'raw'->'data'->>'status' in ('idle','building'))
  or (p_step='baseline' and jsonb_typeof(p_receipt->'raw'->'total_people')='number'
   and (p_receipt->'raw'->>'total_people') ~ '^[0-9]{1,3}$'
   and (p_receipt->'raw'->>'total_people')::integer<jsonb_array_length(p.request->'people_ids'))) then
  return icash_research_private.record_owner_preflight_indexing(p_id,p_lease,p_step,p_receipt);
 end if;
 if p_step='metadata' or (p.indexing_next_step='metadata' and p_step in ('baseline','eligible')) then return 'held';end if;
 if p.receipts ? p_step then return case when p.receipts->p_step=p_receipt then case when p.state='waiting' then 'pending' else p.state end else 'held' end;end if;
 if (p_step='create' and p.state<>'creating') or (p_step<>'create' and p.state<>'checking') or (p_step='eligible' and not p.receipts ? 'baseline') then return 'held';end if;
 update icash_research_private.owner_export_preflights set receipts=receipts||jsonb_build_object(p_step,p_receipt) where id=p.id;
 begin
  raw:=p_receipt->'raw';d:=raw->'data';n:=jsonb_array_length(p.request->'people_ids');
  valid:=p_receipt->'httpStatus'='200'::jsonb and (p_receipt->>'rawText')::jsonb=raw and p.started_at>clock_timestamp()-interval '90 seconds';
  if p_step='create' then
   lid:=d->'list_id';
   valid:=valid and jsonb_typeof(lid) in ('string','number') and (lid#>>'{}') ~ '^[A-Za-z0-9_-]{1,100}$' and d->>'name'=p.list_name and d->>'source_type'='people';
   if valid is true then update icash_research_private.owner_export_preflights set list_id=lid where id=p.id;end if;
   valid:=valid and d->>'status'='completed' and d->'total_count'=to_jsonb(n);
  else
   valid:=valid and jsonb_typeof(raw->'total_people')='number' and (raw->>'total_people') ~ '^[0-9]{1,3}$'
    and (raw->>'total_people')::integer between 0 and n and raw->'total_results'=raw->'total_people'
    and jsonb_typeof(raw->'total_properties')='number' and (raw->>'total_properties') ~ '^[0-9]{1,10}$'
    and not raw ? 'data' and (not raw ? 'credits' or (jsonb_typeof(raw->'credits')='object' and not exists(select 1 from jsonb_each(raw->'credits') c where c.value is distinct from '0'::jsonb)));
   if p_step='baseline' then valid:=valid and raw->'total_people'=to_jsonb(n);end if;
  end if;
 exception when others then valid:=false;
 end;
 if valid is distinct from true then update icash_research_private.owner_export_preflights set state='held',checked_at=clock_timestamp() where id=p.id;return 'held';end if;
 if p_step='create' then update icash_research_private.owner_export_preflights set state='waiting',next_check_at=clock_timestamp()+interval '90 seconds' where id=p.id;return 'pending';end if;
 if p_step='baseline' then return 'checking';end if;
 update icash_research_private.owner_export_preflights set indexing_next_step=null,indexing_reason=null where id=p.id;
 update icash_research_private.owner_export_preflights set state=case when raw->'total_people'='0'::jsonb then 'empty' else 'ready' end,checked_at=clock_timestamp() where id=p.id returning * into p;
 return p.state;
end $function$

CREATE OR REPLACE FUNCTION icash_research_private.record_owner_preflight_indexing(p_id uuid, p_lease uuid, p_step text, p_receipt jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare p icash_research_private.owner_export_preflights;r jsonb;d jsonb;n integer;valid boolean:=false;k text;complete boolean:=false;
begin
 select * into p from icash_research_private.owner_export_preflights where id=p_id for update;
 if not found or p.lease is distinct from p_lease or p_receipt is null or octet_length(p_receipt::text)>2200000
  or p_step not in ('create','metadata','baseline') then return 'held';end if;
 k:=case when p_step='create' then 'create' else 'indexing:'||p_lease||':'||p_step end;
 if p.receipts ? k then return case when p.receipts->k=p_receipt then case when p.state='waiting' then 'pending' else p.state end else 'held' end;end if;
 if (p_step='create' and p.state<>'creating') or (p_step<>'create' and p.state<>'checking')
  or p.deleted_at is not null or p.cleanup_attempts<>0 or p.created_at<=clock_timestamp()-interval '30 minutes'
  or p.created_at>clock_timestamp() or p.started_at<=clock_timestamp()-interval '90 seconds'
  or (p_step<>'create' and not icash_research_private.owner_preflight_list_known(p.id)) then return 'held';end if;
 -- Every observation is appended under its one-use handler, including malformed
 -- metadata. A later successful check never overwrites an earlier zero/error.
 update icash_research_private.owner_export_preflights set receipts=receipts||jsonb_build_object(k,p_receipt) where id=p.id;
 begin
  r:=p_receipt->'raw';d:=r->'data';n:=jsonb_array_length(p.request->'people_ids');
  valid:=p_receipt->'httpStatus'='200'::jsonb and (p_receipt->>'rawText')::jsonb=r and n between 1 and 125
   and (not r ? 'credits' or (jsonb_typeof(r->'credits')='object'
    and not exists(select 1 from jsonb_each(r->'credits') c where c.value is distinct from '0'::jsonb)));
  if p_step in ('create','metadata') then
   valid:=valid and jsonb_typeof(d->'list_id') in ('string','number') and (d->'list_id'#>>'{}') ~ '^[A-Za-z0-9_-]{1,100}$'
    and (p_step='create' or d->'list_id'=p.list_id) and d->>'name'=p.list_name and d->>'source_type'='people'
    and d->>'status' in ('idle','building','completed') and jsonb_typeof(d->'total_count')='number'
    and (d->>'total_count') ~ '^[0-9]{1,3}$' and (d->>'total_count')::integer between 0 and n;
   complete:=valid is true and d->>'status'='completed' and d->'total_count'=to_jsonb(n);
  else
   valid:=valid and icash_research_private.owner_preflight_list_known(p.id,true)
    and jsonb_typeof(r->'total_people')='number' and (r->>'total_people') ~ '^[0-9]{1,3}$'
    and (r->>'total_people')::integer between 0 and n-1 and r->'total_results'=r->'total_people'
    and jsonb_typeof(r->'total_properties')='number' and (r->>'total_properties') ~ '^[0-9]{1,10}$' and not r ? 'data';
  end if;
 exception when others then valid:=false;
 end;
 if valid is distinct from true then
  update icash_research_private.owner_export_preflights set state='held',checked_at=clock_timestamp(),indexing_reason='provider_list_status_invalid' where id=p.id;
  return 'held';
 end if;
 if p_step='create' then
  update icash_research_private.owner_export_preflights set list_id=d->'list_id',state='waiting',next_check_at=least(created_at+interval '30 minutes',clock_timestamp()+interval '90 seconds'),
   indexing_next_step='metadata',indexing_reason='provider_list_building' where id=p.id;
  return 'pending';
 end if;
 if p_step='metadata' and complete then
  update icash_research_private.owner_export_preflights set receipts=receipts||jsonb_build_object('metadata',p_receipt),
   indexing_next_step='baseline',indexing_reason='provider_search_indexing' where id=p.id and not receipts ? 'metadata';
  return 'checking';
 end if;
 if greatest(p.indexing_checks,1)>=6 then
  update icash_research_private.owner_export_preflights set state='held',checked_at=clock_timestamp(),indexing_checks=6,
   indexing_reason='provider_indexing_exhausted' where id=p.id;
  return 'held';
 end if;
 update icash_research_private.owner_export_preflights set state='waiting',indexing_checks=greatest(indexing_checks,1),
  indexing_next_step=case when p_step='metadata' then 'metadata' else 'baseline' end,
  indexing_reason=case when p_step='metadata' then 'provider_list_building' else 'provider_search_indexing' end,
  next_check_at=least(created_at+interval '30 minutes',clock_timestamp()+interval '90 seconds') where id=p.id;
 return 'pending';
end $function$
